668	function buildState(version: number, specs: readonly EndpointSpec[]): LiveState {
669	  const endpoints = new Map<string, LiveEndpoint>();
670	  for (const spec of specs) {
671	    endpoints.set(`${spec.method} ${spec.path}`, {
672	      key: `${spec.method} ${spec.path}`,
673	      responses: spec.responses,
674	      bodyRule: spec.bodyRule,
675	      branches: spec.branches.map((branch) => ({
676	        id: branch.id,
677	        conditions: branch.conditions,
678	        responses: branch.responses,
679	        cursor: 0,
680	      })),
681	      cursor: 0,
682	    });
683	  }
684	  return { version, endpoints };
685	}
