772	// ---------------------------------------------------------------------------
773	// 进程内请求记录
774	// ---------------------------------------------------------------------------
775	//
776	// 仅记录管理范围之外、完整接收且未超过正文上限的请求（场景响应、400、404）。
777	// 未收完整即断开或超出上限不创建记录、不消费序列。
778	// 编号按“完整接收”顺序在进程内单调递增，与接口消费位置是两回事；
779	// 清空与成功/失败重载都保留编号序列，编号不复用。记录只存在内存中，不写文件。
780	
781	// 写出生命周期（仅指服务器侧写出，不表示客户端已收到）：
782	//   pending     —— 已完整接收、计划响应待发送（延迟期间即可查到）
783	//   sent        —— 服务器已完成响应写出；此后连接正常关闭不再改变状态
784	//   interrupted —— 写出完成前连接断开或写入/发送失败
785	type DeliveryStatus = 'pending' | 'sent' | 'interrupted';
786	
787	// 计划响应：场景响应为 'scene'，400/404 等框架响应为 'framework'
788	interface PlannedResponseSnapshot {
789	  readonly kind: 'scene' | 'framework';
790	  readonly status: number;
791	  // 应用层响应头：配置头/框架头 + 服务器填写的准确版本头，不含传输层自动头
792	  readonly headers: { readonly [name: string]: string };
793	  // 配置/框架给出的响应正文文本（不含 HTTP 层按 Content-Length 等补出的字节）
794	  readonly body: string;
795	}
796	
797	interface RequestRecord {
798	  readonly id: number;
799	  readonly receivedAt: string;
800	  readonly request: {
801	    readonly method: string;
802	    // 含查询串的原始请求目标
803	    readonly target: string;
804	    readonly path: string;
805	    // 原始请求头：按在线顺序成对保留，名称大小写与重复头均不折叠
806	    readonly rawHeaders: readonly string[];
807	    readonly bodyBytes: number;
808	    // 正文原始字节的无损表示：合法 UTF-8 时以文本给出，否则以 base64 给出
809	    readonly body: { readonly encoding: 'utf-8' | 'base64'; readonly content: string };
810	  };
811	  // 完整接收那一刻选用的配置版本；在途请求的结论不随之后的 reload 改变
812	  configVersion: number;
813	  // matched=false：未匹配（404），不消费任何序列
814	  matched: boolean;
815	  endpoint: string | null;
816	  // null 表示未做正文校验（GET/未声明规则）；true=通过，false=拒绝并返回 400
817	  bodyValidationPassed: boolean | null;
818	  // 400 时实际返回的差异报告（与响应正文中的 JSON 同一份数据）
819	  bodyRejection: BodyReport | null;
820	  // 场景请求的分支选择：
821	  //   null                 —— 未选择（400/404，或无分支的场景请求之外的情形）；
822	  //   { kind:'fallback' }  —— 无分支命中，使用接口兜底 responses；
823	  //   { kind:'branch', id }—— 命中指定分支，使用该支 responses。
824	  // 无分支接口的场景请求记为 fallback。
825	  branchSelection: { readonly kind: 'branch'; readonly id: string } | { readonly kind: 'fallback' } | null;
826	  // 场景请求在“选中序列”中的消费位置（0 起）；400/404 没有消费位置，记为 null
827	  sequencePosition: number | null;
828	  // 选中序列（命中分支或兜底）的长度；400/404 为 null
829	  sequenceLength: number | null;
830	  plannedResponse: PlannedResponseSnapshot | null;
831	  delivery: DeliveryStatus;
832	}
833	
834	// 已清空记录的投递回调落到空集合上：不取消响应，旧请求之后完成也不得重新出现。
835	class RequestLog {
836	  private records: RequestRecord[] = [];
837	  // 仍可能被投递事件更新的记录 id 集合（清空后旧 id 不在其中）
838	  private readonly live = new Map<number, RequestRecord>();
839	  private nextId = 1;
840	
841	  create(entry: {
842	    method: string;
843	    target: string;
844	    path: string;
845	    rawHeaders: readonly string[];
846	    body: Buffer;
847	    configVersion: number;
848	  }): RequestRecord {
849	    const id = this.nextId;
850	    this.nextId += 1;
851	    const record: RequestRecord = {
852	      id,
853	      receivedAt: new Date().toISOString(),
854	      request: {
855	        method: entry.method,
856	        target: entry.target,
857	        path: entry.path,
858	        rawHeaders: entry.rawHeaders,
859	        bodyBytes: entry.body.byteLength,
860	        body: encodeBodyLosslessly(entry.body),
861	      },
862	      configVersion: entry.configVersion,
863	      matched: false,
864	      endpoint: null,
865	      bodyValidationPassed: null,
866	      bodyRejection: null,
867	      branchSelection: null,
868	      sequencePosition: null,
869	      sequenceLength: null,
870	      plannedResponse: null,
871	      delivery: 'pending',
872	    };
873	    this.records.push(record);
874	    this.live.set(id, record);
875	    return record;
876	  }
877	
878	  // 写出完成；对已清空（不再存活）的记录是 no-op
879	  markDelivered(id: number, status: DeliveryStatus): void {
880	    const record = this.live.get(id);
881	    if (!record) {
882	      return;
883	    }
884	    // 一旦完成写出即为终态：之后的连接正常关闭不得回退为 interrupted
885	    if (record.delivery === 'sent') {
886	      return;
887	    }
888	    record.delivery = status;
889	  }
890	
891	  // 调用时一致快照：拷贝当前存活记录，不推进任何序列
892	  snapshot(): readonly RequestRecord[] {
893	    return [...this.records];
894	  }
