1061	// 返回 null 表示校验通过；否则为可直接序列化的 400 差异报告。
1062	// contentType 为在线顺序第一项 Content-Type 头值（在线：Node 对重复
1063	// content-type 只保留首项；离线 verify：取 rawHeaders 中首个同名头）。
1064	// 正文解码与 JSON 解析不重写原文：BOM 与空白按 UTF-8 解码的默认规则处理，
1065	// 在线与离线对同一组字节给出同一结论。
1066	// 通过时经 parseBodyOnly 另行解析以取得分支选择所用的 JSON 值。
1067	function validateBodyWithContentType(
1068	  contentType: string | undefined,
1069	  body: Buffer,
1070	  rule: BodyRule,
1071	): BodyReport | null {
1072	  const parsed = parseJsonBodyForCheck(contentType, body);
1073	  if ('report' in parsed) {
1074	    return parsed.report;
1075	  }
1076	  const problems: StructureProblem[] = [];
1077	  checkRule(rule, parsed.value, '', problems);
1078	  if (problems.length > 0) {
1079	    return {
1080	      error: 'invalid_request_body',
1081	      stage: 'structure',
1082	      message: `请求正文与接口约定存在 ${problems.length} 处差异`,
1083	      problems,
1084	    };
1085	  }
1086	  return null;
1087	}
