1089	// 媒体类型 -> UTF-8 -> JSON 解析：通过返回 { value }，否则返回 { report }。
1090	// 在线（分支选择）与离线需要同一解析结论，故抽出共用。
1091	function parseJsonBodyForCheck(
1092	  contentType: string | undefined,
1093	  body: Buffer,
1094	): { value: unknown } | { report: BodyReport } {
1095	  const mediaType =
1096	    typeof contentType === 'string' ? contentType.split(';', 1)[0].trim().toLowerCase() : '';
1097	  if (mediaType !== 'application/json') {
1098	    return {
1099	      report: parseFailure(
1100	        typeof contentType === 'string'
1101	          ? `媒体类型不符：期望 application/json（可带参数、忽略大小写），收到 "${contentType}"`
1102	          : '缺少 Content-Type 头：期望 application/json（可带参数、忽略大小写）',
1103	      ),
1104	    };
1105	  }
1106	
1107	  if (body.length === 0) {
1108	    return { report: parseFailure('请求正文为空，无法解析为 JSON') };
1109	  }
1110	
1111	  let text: string;
1112	  try {
1113	    text = new TextDecoder('utf-8', { fatal: true }).decode(body);
1114	  } catch {
1115	    return { report: parseFailure('请求正文不是合法的 UTF-8 编码') };
1116	  }
1117	
1118	  try {
1119	    return { value: JSON.parse(text) };
1120	  } catch (e) {
1121	    return { report: parseFailure(`请求正文不是合法 JSON：${describeError(e)}`) };
1122	  }
1123	}
1124	
1125	// 在线路径：校验媒体类型/UTF-8/JSON/结构，通过时同时返回解析出的 JSON 值
1126	// （供按正文值选择响应分支使用）。
1127	function validateBodyAndParse(
1128	  contentType: string | undefined,
1129	  body: Buffer,
1130	  rule: BodyRule,
1131	): { report: BodyReport } | { value: unknown } {
1132	  const parsed = parseJsonBodyForCheck(contentType, body);
1133	  if ('report' in parsed) {
1134	    return parsed;
1135	  }
1136	  const problems: StructureProblem[] = [];
1137	  checkRule(rule, parsed.value, '', problems);
1138	  if (problems.length > 0) {
1139	    return {
1140	      report: {
1141	        error: 'invalid_request_body',
1142	        stage: 'structure',
1143	        message: `请求正文与接口约定存在 ${problems.length} 处差异`,
1144	        problems,
1145	      },
1146	    };
1147	  }
1148	  return { value: parsed.value };
1149	}
