1238	    const nonNull = rule.enum.find((v) => v !== null);
1239	    return nonNull === undefined ? null : nonNull;
1240	  }
1241	  switch (rule.kind) {
1242	    case 'string':
1243	      return 'contractlab';
1244	    case 'number':
1245	    case 'integer':
