1416	  if (newRule.enum !== undefined) {
1417	    // 旧规则接受整个类型集合，新规则只接受枚举候选
1418	    if (oldRule.kind === 'boolean') {
1419	      for (const value of [false, true]) {
1420	        if (!scalarValueAccepted(newRule, value)) {
1421	          out.push({
1422	            pointer,
1423	            value,
1424	            message: `新规则引入枚举限制（${enumExpectedText(newRule.enum)}），旧规则允许的值 ${JSON.stringify(value)} 不在候选中`,
1425	          });
1426	        }
1427	      }
1428	      return;
1429	    }
1430	    if (oldRule.kind === 'string' || oldRule.kind === 'number' || oldRule.kind === 'integer') {
1431	      // 类型取值无限而枚举有限：构造旧规则接受、但不在新枚举中的见证值
1432	      const witness = freshValueOutsideEnum(oldRule.kind, newRule.enum);
1433	      out.push({
1434	        pointer,
1435	        value: witness,
1436	        message: `新规则引入枚举限制（${enumExpectedText(newRule.enum)}），旧规则允许的值 ${JSON.stringify(witness)} 不在候选中`,
1437	      });
1438	      return;
1439	    }
1440	    return; // oldRule.kind === 'null' 不会到达（调用方已处理）
1441	  }
1442	
1443	  // 双方均无枚举：仅同名兼容，外加 integer 放宽为 number
1444	  const compatible =
1445	    oldRule.kind === newRule.kind || (oldRule.kind === 'integer' && newRule.kind === 'number');
1446	  if (!compatible) {
1447	    // number -> integer 时样本必须是非整数，否则 0 会被新规则接受
1448	    const value =
1449	      oldRule.kind === 'number' && newRule.kind === 'integer' ? 0.5 : sampleValue(oldRule);
1450	    out.push({
1451	      pointer,
1452	      value,
1453	      message: `类型收紧：旧规则接受 ${kindLabel(oldRule)}，新规则只接受 ${newRule.kind}`,
1454	    });
1455	  }
1456	}
