1616	function compareEndpoint(oldEp: EndpointSpec, newEp: EndpointSpec | undefined): EndpointReport {
1617	  const base = { method: oldEp.method, path: oldEp.path };
1618	
1619	  if (!newEp) {
1620	    return {
1621	      ...base,
1622	      compatible: false,
1623	      reasons: [
1624	        { message: '新配置中不存在该接口：按 方法 + 字面路径 匹配不到，旧客户端的调用将得到 404' },
1625	      ],
1626	      example: acceptedRequestExample(oldEp),
1627	    };
1628	  }
1629	
1630	  if (!oldEp.bodyRule && !newEp.bodyRule) {
1631	    return { ...base, compatible: true, reasons: [] };
1632	  }
1633	
1634	  if (!oldEp.bodyRule && newEp.bodyRule) {
1635	    // 旧版允许任意媒体类型与正文；新版启用校验即存在被拒绝的旧请求
1636	    return {
1637	      ...base,
1638	      compatible: false,
1639	      reasons: [
1640	        {
1641	          pointer: '',
1642	          message: '旧接口不校验请求正文（任意媒体类型与正文均可），新接口启用了 requestBody 正文校验',
1643	        },
1644	      ],
1645	      example: {
1646	        ...base,
1647	        headers: { 'Content-Type': 'application/json' },
1648	        body: JSON.stringify(violateValue(newEp.bodyRule)),
1649	      },
1650	    };
1651	  }
1652	
1653	  if (oldEp.bodyRule && !newEp.bodyRule) {
1654	    return { ...base, compatible: true, reasons: [] }; // 移除规则更宽松
1655	  }
1656	
1657	  const violations: BodyViolation[] = [];
1658	  collectViolations(oldEp.bodyRule as BodyRule, newEp.bodyRule as BodyRule, '', violations);
1659	  if (violations.length === 0) {
1660	    return { ...base, compatible: true, reasons: [] };
1661	  }
1662	  return {
1663	    ...base,
1664	    compatible: false,
1665	    reasons: violations.map((v) => ({ pointer: v.pointer, message: v.message })),
1666	    example: {
1667	      ...base,
1668	      headers: { 'Content-Type': 'application/json' },
1669	      body: JSON.stringify(violations[0].value),
1670	    },
1671	  };
1672	}
