1674	function compareConfigs(
1675	  oldSpecs: readonly EndpointSpec[],
1676	  newSpecs: readonly EndpointSpec[],
1677	  oldFile: string,
1678	  newFile: string,
1679	): CompareReport {
1680	  const newByKey = new Map<string, EndpointSpec>();
1681	  for (const spec of newSpecs) {
1682	    newByKey.set(`${spec.method} ${spec.path}`, spec);
1683	  }
1684	  const endpoints = oldSpecs.map((spec) =>
1685	    compareEndpoint(spec, newByKey.get(`${spec.method} ${spec.path}`)),
1686	  );
1687	  return {
1688	    compatible: endpoints.every((ep) => ep.compatible),
1689	    oldFile,
1690	    newFile,
1691	    endpoints,
1692	  };
1693	}
