1695	async function runCompare(oldArg: string, newArg: string): Promise<never> {
1696	  const oldFile = path.resolve(oldArg);
1697	  const newFile = path.resolve(newArg);
1698	
1699	  const attempt = async (
1700	    file: string,
1701	  ): Promise<{ specs?: EndpointSpec[]; error?: string }> => {
1702	    try {
1703	      return { specs: await loadSpecsFromFile(file) };
1704	    } catch (e) {
1705	      return { error: describeError(e) };
1706	    }
1707	  };
1708	
1709	  // 两份文件都完整经历 读取 -> 解析 -> 严格校验；任一失败则不输出任何报告
1710	  const [oldResult, newResult] = await Promise.all([attempt(oldFile), attempt(newFile)]);
1711	  let failed = false;
1712	  if (oldResult.error !== undefined) {
1713	    process.stderr.write(`${APP_NAME}: compare 旧文件：${oldResult.error}\n`);
1714	    failed = true;
1715	  }
1716	  if (newResult.error !== undefined) {
1717	    process.stderr.write(`${APP_NAME}: compare 新文件：${newResult.error}\n`);
1718	    failed = true;
1719	  }
1720	  if (failed) {
1721	    process.exit(2);
1722	  }
1723	
1724	  const report = compareConfigs(
1725	    oldResult.specs as EndpointSpec[],
1726	    newResult.specs as EndpointSpec[],
1727	    oldFile,
1728	    newFile,
1729	  );
1730	  process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
1731	  process.exit(report.compatible ? 0 : 1);
1732	}
