1734	// ---------------------------------------------------------------------------
1735	// OpenAPI 请求正文约定导入（import 子命令）
1736	// ---------------------------------------------------------------------------
1737	//
1738	// 读取本地 OpenAPI 3.0 JSON 与现有场景配置，按“方法 + 字面路径”为每个场景
1739	// 接口选择文档操作，仅用操作 requestBody 转换出的正文规则替换接口的
1740	// requestBody（保留接口顺序与 responses），把可直接用于 serve / compare 的
1741	// 新场景 JSON 写往 stdout。不监听端口、不联网、不修改输入文件。
1742	//
1743	// 转换约定：
1744	// - 场景每个接口都必须在文档 paths 中找到同路径、同方法的操作，否则拒绝；
1745	// - GET 操作声明 requestBody 拒绝；POST 未声明 requestBody 时移除接口旧规则；
1746	// - POST 的 requestBody 必须 required=true，content 仅含 application/json
1747	//   且带 schema，否则拒绝；
1748	// - schema 支持 object/array/string/number/integer/boolean、递归
1749	//   properties/required/items、布尔 additionalProperties（缺省按 OpenAPI
1750	//   语义为允许，并在输出中显式写出）、布尔 nullable（true 在转换结果的
1751	//   接受集合上加入 null，false 或省略不变，非布尔值拒绝）与标量 enum
1752	//   （非空候选数组，逐项符合类型与可空约定；object/array schema 与 allOf
1753	//   组合节点禁止 enum）；无 type 的 allOf 组合节点仍只允许 nullable:false
1754	//   或省略；title/description/example 可忽略，其余关键字或非法值一律拒绝；
1755	// - 支持本文件内 $ref（按 JSON Pointer 转义解析）：共享引用允许，目标缺失、
1756	//   外部引用与循环引用拒绝并给出引用链；引用节点只含 $ref；
1757	// - 支持纯对象 allOf：组合节点仅含 allOf 与上述注释，分支可引用或任意深度
1758	//   嵌套组合（嵌套 allOf 展平为全部对象叶分支）；按所选操作最终请求正文的
1759	//   整体接受集合求各分支交集，结论与分支顺序、嵌套分组、本文件内引用无关；
1760	//   同名字段（对象内部与数组元素）递归相交、number∩integer 取 integer、
1761	//   必填合并、各分支额外字段限制同时生效；交集含 null 当且仅当全部分支都
1762	//   接受 null（nullable:true），非 null 部分按结构求交，仅剩 null 时输出
1763	//   type:null；区分字段禁止出现、整体空交集与非空但无法表达，后两者定位
1764	//   原因并拒绝，不扩展规则种类；
1765	// - 未被场景选中的操作与不可达定义不参与转换（其中的错误不影响结果）；
1766	//   全部输入与所选可达定义有效后才输出，成功退出 0，失败退出 2
1767	//   （stderr 指明文件与操作或定义位置，stdout 为空）。
1768	
1769	class ImportError extends Error {
1770	  constructor(message: string) {
1771	    super(message);
1772	    this.name = 'ImportError';
1773	  }
1774	}
