2763	// utf-8 文本必须能无损编码往返：孤立代理项（lone surrogate）按 UTF-8 编码时
2764	// 会被替换为 U+FFFD，即使替换后的字节数恰好与 bodyBytes 吻合也不再是原始字节，
2765	// 必须拒绝（verify 与 replay 共用此校验）。
2766	function hasLoneSurrogate(text: string): boolean {
2767	  for (let i = 0; i < text.length; i += 1) {
2768	    const code = text.charCodeAt(i);
2769	    if (code >= 0xd800 && code <= 0xdbff) {
2770	      const next = text.charCodeAt(i + 1);
2771	      if (!(next >= 0xdc00 && next <= 0xdfff)) {
2772	        return true; // 高代理项后未跟低代理项
2773	      }
2774	      i += 1; // 跳过完整代理对
2775	    } else if (code >= 0xdc00 && code <= 0xdfff) {
2776	      return true; // 孤立的低代理项
2777	    }
2778	  }
2779	  return false;
2780	}
