2966	function verifyRequests(
2967	  requests: readonly SnapshotRequest[],
2968	  specs: readonly EndpointSpec[],
2969	  requestsFile: string,
2970	  configFile: string,
2971	): VerifyReport {
2972	  const byKey = new Map<string, EndpointSpec>();
2973	  for (const spec of specs) {
2974	    byKey.set(`${spec.method} ${spec.path}`, spec);
2975	  }
2976	  const results = requests.map((req): VerifyResultEntry => {
2977	    const endpoint =
2978	      req.method === 'GET' || req.method === 'POST'
2979	        ? byKey.get(`${req.method} ${req.path}`)
2980	        : undefined;
2981	    if (!endpoint) {
2982	      return { id: req.id, outcome: 'unmatched', endpoint: null };
2983	    }
2984	    const key = `${endpoint.method} ${endpoint.path}`;
2985	    if (endpoint.bodyRule) {
2986	      const rejection = validateBodyWithContentType(req.contentType, req.body, endpoint.bodyRule);
2987	      if (rejection) {
2988	        return { id: req.id, outcome: 'rejected', endpoint: key, rejection };
2989	      }
2990	      return { id: req.id, outcome: 'passed', endpoint: key };
2991	    }
2992	    return { id: req.id, outcome: 'no_body_check', endpoint: key };
2993	  });
2994	  const accepted = results.filter(
2995	    (r) => r.outcome === 'passed' || r.outcome === 'no_body_check',
2996	  ).length;
2997	  return {
2998	    requestsFile,
2999	    configFile,
3000	    total: results.length,
3001	    accepted,
3002	    rejected: results.length - accepted,
3003	    results,
3004	  };
3005	}
