3078	  'host',
3079	  'expect',
3080	  'connection',
3081	  'keep-alive',
3082	  'content-length',
3083	  'transfer-encoding',
3084	  'te',
3085	  'trailer',
3086	  'upgrade',
3087	  'proxy-authenticate',
3088	  'proxy-authorization',
