3094	  readonly method: 'GET' | 'POST';
3095	  // 原样发送的请求目标（含查询串与百分号编码，不归一化）
3096	  readonly target: string;
3097	  // target 去掉查询串后的字面路径（比较策略按“方法 + 路径”选择接口）
