3109	  if (target.length === 0 || !target.startsWith('/')) {
3110	    snapshotFail(where, `必须是以 "/" 开头的 HTTP 请求目标，收到 ${JSON.stringify(target)}`);
3111	  }
3112	  for (const ch of target) {
3113	    const code = ch.charCodeAt(0);
3114	    if (code <= 0x20 || code === 0x7f) {
3115	      snapshotFail(where, `含空白或控制字符，不是合法的 HTTP 请求目标：${JSON.stringify(target)}`);
3116	    }
3117	    if (code > 0xff) {
3118	      snapshotFail(where, `含 Latin-1 之外的字符，无法作为 HTTP 请求目标发送：${JSON.stringify(target)}`);
3119	    }
3120	  }
