3125	function filterReplayHeaders(
3126	  rawHeaders: readonly string[],
3127	  where: string,
3128	): [string, string][] {
3129	  const connectionNamed = new Set<string>();
3130	  for (let j = 0; j + 1 < rawHeaders.length; j += 2) {
3131	    if ((rawHeaders[j] as string).toLowerCase() === 'connection') {
3132	      for (const token of (rawHeaders[j + 1] as string).split(',')) {
3133	        const name = token.trim().toLowerCase();
3134	        if (name !== '') {
3135	          connectionNamed.add(name);
3136	        }
3137	      }
3138	    }
3139	  }
3140	  const out: [string, string][] = [];
3141	  for (let j = 0; j + 1 < rawHeaders.length; j += 2) {
3142	    const name = rawHeaders[j] as string;
3143	    const value = rawHeaders[j + 1] as string;
3144	    const lower = name.toLowerCase();
3145	    if (REPLAY_STRIP_HEADERS.has(lower) || connectionNamed.has(lower)) {
3146	      continue;
3147	    }
3148	    if (!HEADER_NAME_RE.test(name)) {
3149	      snapshotFail(`${where}[${j}]`, `不是可发送的 HTTP 头名称：${JSON.stringify(name)}`);
3150	    }
3151	    for (let k = 0; k < value.length; k += 1) {
3152	      const code = value.charCodeAt(k);
3153	      // 与响应头同一规则：允许水平制表符；拒绝换行及其余控制字符；仅 Latin-1
3154	      if ((code <= 0x1f && code !== 0x09) || code === 0x7f || code > 0xff) {
