3156	          `${where}[${j + 1}]`,
3157	          `头 ${JSON.stringify(name)} 的值不得包含换行或其他控制字符，且只能使用 Latin-1 字符`,
3158	        );
3159	      }
3160	    }
3161	    out.push([name, value]);
3162	  }
3163	  return out;
3164	}
