3442	// 解析 JSON 语义比较的一侧正文文本：仅可剥离单个开头 BOM；空正文非法。
3443	// 忽略规则不豁免解析——两侧都必须先通过本解析。
3444	function parseSemanticJson(text: string): { readonly ok: true; readonly value: unknown } | { readonly ok: false; readonly reason: string } {
3445	  const stripped = text.startsWith('\uFEFF') ? text.slice(1) : text;
3446	  if (stripped === '') {
3447	    return { ok: false, reason: '是空正文，不是合法 JSON' };
3448	  }
3449	  try {
3450	    return { ok: true, value: JSON.parse(stripped) };
3451	  } catch (e) {
3452	    return { ok: false, reason: `不是合法 JSON：${describeError(e)}` };
3453	  }
3454	}
