3456	// 严格 UTF-8 解码（保留开头 BOM 字符，交由 parseSemanticJson 统一处理）
3457	function decodeUtf8Strict(body: Buffer): { readonly ok: true; readonly text: string } | { readonly ok: false; readonly reason: string } {
3458	  try {
3459	    return { ok: true, text: new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(body) };
3460	  } catch {
3461	    return { ok: false, reason: '不是合法 UTF-8' };
3462	  }
