3476	// ---------------------------------------------------------------------------
3477	// 数组业务键对齐（策略 align，可选）
3478	// ---------------------------------------------------------------------------
3479	
3480	// 对齐数组元素键：字符串、有限数字或布尔（null 不能作键，不做类型转换）
3481	type AlignKeyValue = string | number | boolean;
3482	
3483	// 一个已校验元素在对齐数组中的位置与键
3484	interface AlignKeyEntry {
3485	  readonly index: number;
3486	  readonly key: AlignKeyValue;
3487	}
