3489	// 对齐校验问题：正文中的 RFC 6901 位置（根为 ""）与原因
3490	interface AlignProblem {
3491	  readonly pointer: string;
3492	  readonly reason: string;
3493	}
3494	
3495	// 键比较严格按类型：字符串/数字/布尔互不转换；数字 0 与 -0 等价（String(-0) 为 "0"）
3496	function alignCompositeKey(key: AlignKeyValue): string {
3497	  return `${typeof key}:${String(key)}`;
3498	}
