3500	// 校验对齐数组并建立 键 -> 元素 映射（忽略不豁免键完整性与唯一性校验）：
3501	// 元素须为对象，键字段须存在且为字符串、有限数字或布尔值，同一数组内唯一。
3502	// 失败返回首个可定位问题（位置 + 原因）。
3503	function buildAlignKeyMap(
3504	  arr: readonly unknown[],
3505	  keyField: string,
3506	  arrayPointer: string,
3507	): { readonly map: Map<string, AlignKeyEntry> } | { readonly problem: AlignProblem } {
3508	  const map = new Map<string, AlignKeyEntry>();
3509	  for (let i = 0; i < arr.length; i += 1) {
3510	    const element = arr[i];
3511	    const elementPointer = `${arrayPointer}/${i}`;
3512	    if (!isPlainObject(element)) {
3513	      return {
3514	        problem: { pointer: elementPointer, reason: `对齐数组元素必须是对象，收到 ${jsonTypeOf(element)}` },
3515	      };
3516	    }
3517	    // 自有字段：空字段名与 "__proto__" 都是普通字段
3518	    if (!Object.prototype.hasOwnProperty.call(element, keyField)) {
3519	      return {
3520	        problem: { pointer: elementPointer, reason: `对齐数组元素缺少键字段 ${JSON.stringify(keyField)}` },
3521	      };
3522	    }
3523	    const key: unknown = element[keyField];
3524	    const valid =
3525	      typeof key === 'string' ||
3526	      typeof key === 'boolean' ||
3527	      (typeof key === 'number' && Number.isFinite(key));
3528	    if (!valid) {
3529	      return {
3530	        problem: {
3531	          pointer: `${elementPointer}/${escapePointerSegment(keyField)}`,
3532	          reason: `对齐键必须是字符串、有限数字或布尔值（null 不能作键、不做类型转换），收到 ${jsonTypeOf(key)}`,
3533	        },
3534	      };
3535	    }
3536	    const composite = alignCompositeKey(key as AlignKeyValue);
3537	    const existing = map.get(composite);
3538	    if (existing !== undefined) {
3539	      return {
3540	        problem: {
3541	          pointer: elementPointer,
3542	          reason: `对齐键 ${JSON.stringify(key)} 在同一数组内重复（另见下标 ${existing.index}）`,
3543	        },
3544	      };
3545	    }
3546	    map.set(composite, { index: i, key: key as AlignKeyValue });
3547	  }
3548	  return { map };
3549	}
