3551	// 校验一侧正文在某个对齐位置上的值：位置不存在返回 null（允许）；存在时须为
3552	// 数组且元素/键合法——合法返回键映射，否则返回可定位问题。
3553	function checkAlignTarget(
3554	  root: unknown,
3555	  spec: AlignSpec,
3556	): { readonly keys: Map<string, AlignKeyEntry> } | { readonly problem: AlignProblem } | null {
3557	  const node = resolvePointer(root, spec.segments);
3558	  if (node === undefined) {
3559	    return null; // 位置不存在允许
3560	  }
3561	  if (!Array.isArray(node)) {
3562	    return {
3563	      problem: { pointer: spec.pointer, reason: `对齐位置存在但不是数组，收到 ${jsonTypeOf(node)}` },
3564	    };
3565	  }
3566	  const built = buildAlignKeyMap(node, spec.key, spec.pointer);
3567	  if ('problem' in built) {
3568	    return built;
3569	  }
3570	  return { keys: built.map };
3571	}
