3573	// 对齐数组内的元素差异明细：业务键、存在侧在原始正文中的 RFC 6901 位置、
3574	// 计划与实际值及双方独立存在性标记——缺失不以 null 或字符串 "missing" 表示，
3575	// 由 *Exists 标记独立给出（该侧不存在时值字段为 null 且对应 *Pointer 省略）。
3576	interface AlignedDifference {
3577	  // 对齐数组位置（规范化指针，根为 ""）
3578	  readonly array: string;
3579	  readonly keyField: string;
3580	  readonly key: AlignKeyValue;
3581	  readonly plannedPointer?: string;
3582	  readonly actualPointer?: string;
3583	  readonly plannedExists: boolean;
3584	  readonly actualExists: boolean;
3585	  readonly planned: unknown;
3586	  readonly actual: unknown;
3587	}
