3589	interface BodyDiffOut {
3590	  // 未忽略的普通差异（对齐数组之外，或对齐位置在某侧非法时的下标回退）
3591	  readonly differences: BodyDifference[];
3592	  // 对齐数组内的元素差异明细
3593	  readonly aligned: AlignedDifference[];
3594	}
3595	
3596	// 一次正文比较所需的全部上下文
3597	interface JsonDiffContext {
3598	  readonly ignore: ReadonlySet<string>;
3599	  readonly align: ReadonlyMap<string, AlignSpec>;
3600	  // 对齐位置 -> 该侧已校验的 键 -> 元素 映射（仅含位置存在且合法的一侧）
3601	  readonly plannedKeys: ReadonlyMap<string, Map<string, AlignKeyEntry>>;
3602	  readonly actualKeys: ReadonlyMap<string, Map<string, AlignKeyEntry>>;
3603	}
3604	
3605	// 当前递归位置所属的对齐元素（在对齐数组的配对元素内部时存在）
3606	interface AlignedElementContext {
3607	  readonly array: string;
3608	  readonly keyField: string;
3609	  readonly key: AlignKeyValue;
3610	}
