3612	// 记录一处节点差异：对齐元素内部走 AlignedDifference（双方独立存在性标记，
3613	// 缺失侧值为 null、位置省略），其余保持原有 BodyDifference（缺失记 "missing"）
3614	function pushNodeDiff(
3615	  out: BodyDiffOut,
3616	  alignedCtx: AlignedElementContext | undefined,
3617	  plannedPath: readonly string[],
3618	  actualPath: readonly string[],
3619	  planned: unknown,
3620	  actual: unknown,
3621	  plannedExists: boolean,
3622	  actualExists: boolean,
3623	): void {
3624	  if (alignedCtx === undefined) {
3625	    out.differences.push({
3626	      pointer: canonicalPointer(plannedPath),
3627	      planned: plannedExists ? planned : MISSING_NODE,
3628	      actual: actualExists ? actual : MISSING_NODE,
3629	    });
3630	    return;
3631	  }
3632	  out.aligned.push({
3633	    array: alignedCtx.array,
3634	    keyField: alignedCtx.keyField,
3635	    key: alignedCtx.key,
3636	    ...(plannedExists ? { plannedPointer: canonicalPointer(plannedPath) } : {}),
3637	    ...(actualExists ? { actualPointer: canonicalPointer(actualPath) } : {}),
3638	    plannedExists,
3639	    actualExists,
3640	    planned: plannedExists ? planned : null,
3641	    actual: actualExists ? actual : null,
3642	  });
3643	}
