3645	// 递归列出全部未忽略的独立正文差异：节点缺失或类型不同只报该节点，不再深入。
3646	// plannedPath / actualPath 分别跟踪两侧在原始正文中的位置（仅在对齐数组的
3647	// 配对元素内部才会不同）；忽略指针一律以计划侧位置（plannedPath）判定。
3648	function diffJsonValues(
3649	  planned: unknown,
3650	  actual: unknown,
3651	  ctx: JsonDiffContext,
3652	  plannedPath: readonly string[],
3653	  actualPath: readonly string[],
3654	  out: BodyDiffOut,
3655	  alignedCtx?: AlignedElementContext,
3656	): void {
3657	  if (ctx.ignore.has(canonicalPointer(plannedPath))) {
3658	    return; // 忽略指针处的值、存在性与子树
3659	  }
3660	  const plannedType = jsonTypeOf(planned);
3661	  const actualType = jsonTypeOf(actual);
3662	  if (plannedType !== actualType) {
3663	    pushNodeDiff(out, alignedCtx, plannedPath, actualPath, planned, actual, true, true);
3664	    return;
3665	  }
3666	  if (plannedType === 'object') {
3667	    // 只看自有字段，忽略键顺序（含空字段名与 __proto__）
3668	    const p = planned as Record<string, unknown>;
3669	    const a = actual as Record<string, unknown>;
3670	    for (const key of Object.keys(p)) {
3671	      const childPlannedPath = [...plannedPath, key];
3672	      const childActualPath = [...actualPath, key];
3673	      if (Object.prototype.hasOwnProperty.call(a, key)) {
3674	        diffJsonValues(p[key], a[key], ctx, childPlannedPath, childActualPath, out, alignedCtx);
3675	      } else if (!ctx.ignore.has(canonicalPointer(childPlannedPath))) {
3676	        pushNodeDiff(out, alignedCtx, childPlannedPath, childActualPath, p[key], undefined, true, false);
3677	      }
3678	    }
3679	    for (const key of Object.keys(a)) {
3680	      if (!Object.prototype.hasOwnProperty.call(p, key)) {
3681	        const childPlannedPath = [...plannedPath, key];
3682	        const childActualPath = [...actualPath, key];
3683	        if (!ctx.ignore.has(canonicalPointer(childPlannedPath))) {
3684	          pushNodeDiff(out, alignedCtx, childPlannedPath, childActualPath, undefined, a[key], false, true);
3685	        }
3686	      }
3687	    }
3688	    return;
3689	  }
3690	  if (plannedType === 'array') {
3691	    // 配置了对齐且两侧该位置都合法：按键配对，顺序不影响结论
3692	    const pointer = canonicalPointer(plannedPath);
3693	    const spec = ctx.align.get(pointer);
3694	    const plannedKeys = spec === undefined ? undefined : ctx.plannedKeys.get(pointer);
3695	    const actualKeys = spec === undefined ? undefined : ctx.actualKeys.get(pointer);
3696	    if (spec !== undefined && plannedKeys !== undefined && actualKeys !== undefined) {
3697	      diffAlignedArray(
3698	        planned as unknown[],
3699	        actual as unknown[],
3700	        spec,
3701	        plannedKeys,
3702	        actualKeys,
3703	        ctx,
3704	        plannedPath,
3705	        actualPath,
3706	        out,
3707	      );
3708	      return;
3709	    }
3710	    // 按原下标比较：顺序有意义；多出或缺失的元素在其下标报告，不另报长度；
3711	    // 被忽略的下标不参与比较，但不删除数组项、不移动其余下标
3712	    const p = planned as unknown[];
3713	    const a = actual as unknown[];
3714	    const n = Math.max(p.length, a.length);
3715	    for (let i = 0; i < n; i += 1) {
3716	      const childPlannedPath = [...plannedPath, String(i)];
3717	      const childActualPath = [...actualPath, String(i)];
3718	      if (ctx.ignore.has(canonicalPointer(childPlannedPath))) {
3719	        continue;
3720	      }
3721	      if (i >= p.length) {
3722	        pushNodeDiff(out, alignedCtx, childPlannedPath, childActualPath, undefined, a[i], false, true);
3723	      } else if (i >= a.length) {
3724	        pushNodeDiff(out, alignedCtx, childPlannedPath, childActualPath, p[i], undefined, true, false);
3725	      } else {
3726	        diffJsonValues(p[i], a[i], ctx, childPlannedPath, childActualPath, out, alignedCtx);
3727	      }
3728	    }
3729	    return;
3730	  }
3731	  // 标量不转换类型；数字按解析数值比较（0 与 -0 等价）
3732	  if (planned !== actual) {
3733	    pushNodeDiff(out, alignedCtx, plannedPath, actualPath, planned, actual, true, true);
3734	  }
3735	}
3736	
3737	// 对齐数组按键配对比较：两侧数组按键配对，顺序不影响结论；同键元素递归比较
3738	// 全部未忽略差异；只在一侧出现的键报告整个元素，不深入。忽略指针以计划原
3739	// 下标定位（包括缺失元素）；仅实际侧存在的新键不能被其他下标的忽略项遮蔽；
3740	// 忽略不改变配对身份（与被忽略计划元素同键的实际元素仍属已配对）。
3741	function diffAlignedArray(
3742	  planned: readonly unknown[],
3743	  actual: readonly unknown[],
3744	  spec: AlignSpec,
3745	  plannedKeys: Map<string, AlignKeyEntry>,
3746	  actualKeys: Map<string, AlignKeyEntry>,
3747	  ctx: JsonDiffContext,
3748	  plannedPath: readonly string[],
3749	  actualPath: readonly string[],
3750	  out: BodyDiffOut,
3751	): void {
3752	  const arrayPointer = canonicalPointer(plannedPath);
3753	  // 计划侧按原下标顺序：配对或报告“仅计划侧存在”
3754	  for (const [composite, p] of plannedKeys) {
3755	    const childPlannedPath = [...plannedPath, String(p.index)];
3756	    if (ctx.ignore.has(canonicalPointer(childPlannedPath))) {
3757	      continue; // 被忽略的计划元素：配对身份不变，但不产生任何差异
3758	    }
3759	    const alignedCtx: AlignedElementContext = { array: arrayPointer, keyField: spec.key, key: p.key };
3760	    const a = actualKeys.get(composite);
3761	    if (a === undefined) {
3762	      // 键仅计划侧存在：报告整个元素，不深入
3763	      pushNodeDiff(out, alignedCtx, childPlannedPath, childPlannedPath, planned[p.index], undefined, true, false);
3764	    } else {
3765	      const childActualPath = [...actualPath, String(a.index)];
3766	      diffJsonValues(planned[p.index], actual[a.index], ctx, childPlannedPath, childActualPath, out, alignedCtx);
3767	    }
3768	  }
3769	  // 实际侧按原下标顺序：报告“仅实际侧存在”的新键（不被其他下标的忽略项遮蔽）
3770	  for (const [composite, a] of actualKeys) {
3771	    if (plannedKeys.has(composite)) {
3772	      continue; // 已配对（含与被忽略计划元素配对）
3773	    }
3774	    const childActualPath = [...actualPath, String(a.index)];
3775	    const alignedCtx: AlignedElementContext = { array: arrayPointer, keyField: spec.key, key: a.key };
3776	    pushNodeDiff(out, alignedCtx, childActualPath, childActualPath, undefined, actual[a.index], false, true);
3777	  }
3778	}
