3780	interface ReplayResponse {
3781	  readonly status: number;
3782	  readonly body: Buffer;
3783	}
3784	
3785	type ReplayExchange =
3786	  | { readonly ok: true; readonly response: ReplayResponse }
3787	  | { readonly ok: false; readonly reason: string };
3788	
3789	// 重放单条请求：独立连接、只尝试一次、不跟随重定向；总超时自开始连接覆盖
3790	// 完整收发，不因持续来数据而延长。通信失败时关闭连接并返回原因。
3791	function replayOne(port: number, request: ReplayRequest, timeoutMs: number): Promise<ReplayExchange> {
3792	  return new Promise((resolve) => {
3793	    let settled = false;
3794	    const done = (outcome: ReplayExchange): void => {
3795	      if (!settled) {
3796	        settled = true;
3797	        clearTimeout(timer);
3798	        resolve(outcome);
3799	      }
3800	    };
3801	
3802	    // 业务头在前（原顺序/大小写/重复项），随后按目标与实际字节数重建
3803	    // Host 与 Content-Length；每条请求独立连接，响应结束后关闭。
3804	    const headers: string[] = [];
3805	    for (const [name, value] of request.headers) {
3806	      headers.push(name, value);
3807	    }
3808	    headers.push('Host', `127.0.0.1:${port}`);
3809	    headers.push('Content-Length', String(request.body.byteLength));
3810	    headers.push('Connection', 'close');
3811	
3812	    const req = http.request({
3813	      host: '127.0.0.1',
3814	      port,
3815	      method: request.method,
3816	      path: request.target, // 原样发送：保留查询串与百分号编码，不归一化
3817	      headers,
3818	      agent: false, // 不连接池化：一次一条，每条只尝试一次
3819	    });
3820	
3821	    // 总超时：覆盖连接建立与完整收发，持续来数据不延长
3822	    const timer = setTimeout(() => {
3823	      req.destroy();
3824	      done({ ok: false, reason: `超过总超时 ${timeoutMs}ms（自开始连接覆盖完整收发）` });
3825	    }, timeoutMs);
3826	
3827	    req.on('response', (res) => {
3828	      const chunks: Buffer[] = [];
3829	      res.on('data', (chunk: Buffer) => chunks.push(chunk));
3830	      res.on('end', () => {
3831	        done({
3832	          ok: true,
3833	          response: { status: res.statusCode ?? 0, body: Buffer.concat(chunks) },
3834	        });
3835	      });
3836	      res.on('aborted', () => {
3837	        done({ ok: false, reason: '响应中途断开（部分响应不算完整）' });
3838	      });
3839	      res.on('error', (e: unknown) => {
3840	        done({ ok: false, reason: `响应读取失败：${describeError(e)}` });
3841	      });
3842	      res.on('close', () => {
3843	        if (!res.complete) {
3844	          done({ ok: false, reason: '响应中途断开（部分响应不算完整）' });
3845	        }
3846	      });
3847	    });
3848	    req.on('error', (e: Error) => {
3849	      done({ ok: false, reason: `通信失败：${e.message}` });
3850	    });
3851	    req.end(request.body);
3852	  });
3853	}
