3855	// 完整响应的无损 JSON 表示（与请求记录正文同一套编码规则）
3856	function replayResponseJson(response: ReplayResponse): {
3857	  status: number;
3858	  body: { encoding: 'utf-8' | 'base64'; content: string };
3859	} {
3860	  return { status: response.status, body: encodeBodyLosslessly(response.body) };
