4200	// null 仅当规则接受 null（nullable 且枚举含 null，或 type:"null"）才可行。
4201	function scalarConditionConflict(
4202	  rule: Extract<BodyRule, { kind: ScalarKind }>,
4203	  value: BranchConditionValue,
4204	): { kind: 'type' | 'enum' | 'null' } | null {
4205	  if (value === null) {
