4494	  private nodeOf(segments: readonly string[]): ReachNode {
4495	    let node = this.rootNode;
4496	    for (let k = 0; k < segments.length - 1; k += 1) {
4497	      node = node.children.get(segments[k]) as ReachNode;
4498	    }
4499	    return node;
4500	  }
