4502	  // 一支条件是否被正文全部满足：沿指针取值，取不到（祖先缺失、祖先为 null、
4503	  // 在标量/数组上深入、字段缺失）即不匹配；严格相等、不做类型转换。
4504	  private satisfies(conditions: readonly BranchCondition[], value: unknown): boolean {
4505	    for (const condition of conditions) {
4506	      const actual = resolvePointer(value, condition.segments);
4507	      if (actual === undefined || actual !== condition.value) {
4508	        return false;
4509	      }
4510	    }
4511	    return true;
4512	  }
4513	
4514	  private firstMatch(value: unknown): number | null {
4515	    for (let i = 0; i < this.branches.length; i += 1) {
4516	      if (this.satisfies(this.branches[i].conditions, value)) {
4517	        return i;
4518	      }
4519	    }
4520	    return null;
4521	  }
