4523	  // 某节点对象的最小合格样本：含全部必填字段（含未引用的对象/数组/标量字段，
4524	  // 递归取最小合格值）；字段名可能为 "" 或 "__proto__"，用无原型对象。
4525	  private baseObject(node: ReachNode): Record<string, unknown> {
4526	    const obj: Record<string, unknown> = Object.create(null);
4527	    for (const [name, field] of node.objectRule.fields) {
4528	      if (field.required) {
4529	        obj[name] = sampleValue(field.rule);
4530	      }
4531	    }
4532	    return obj;
4533	  }
