4535	  private allNodes(): readonly ReachNode[] {
4536	    const out: ReachNode[] = [];
4537	    const walk = (node: ReachNode): void => {
4538	      out.push(node);
4539	      for (const child of node.children.values()) {
4540	        walk(child);
4541	      }
4542	    };
4543	    walk(this.rootNode);
4544	    return out;
4545	  }
