4547	  // 按钉值表与谓词枚举合格根对象，返回第一个满足谓词者；都不满足返回 NO_WITNESS。
4548	  private findObject(
4549	    pins: PinMap,
4550	    predicate: (value: unknown) => boolean,
4551	  ): Record<string, unknown> | typeof NO_WITNESS {
4552	    // 每个约束节点一个持久工作对象（节点“存在”布局时挂到父对象对应字段上）
4553	    const work = new Map<ReachNode, Record<string, unknown>>();
4554	    for (const node of this.allNodes()) {
4555	      work.set(node, this.baseObject(node));
4556	    }
4557	    const rootObj = work.get(this.rootNode) as Record<string, unknown>;
4558	
4559	    // 中间对象节点（不含根），按深度从小到大枚举/物化（父先于子）
4560	    const innerNodes = this.allNodes().slice(1);
4561	    innerNodes.sort((a, b) => a.path.length - b.path.length);
4562	    // 每节点布局数：可选多一个“缺失”，可空多一个“null”，恒有“存在”。
4563	    // 必填不可空：仅存在；必填可空：null/存在；可选不可空：缺失/存在；
4564	    // 可选可空：缺失/null/存在。
4565	    const layouts = innerNodes.map((node) => {
4566	      const field = (node.parent as ReachNode).objectRule.fields.get(node.fieldName as string) as FieldRule;
4567	      return (field.required ? 0 : 1) + (ruleAcceptsNullValue(field.rule) ? 1 : 0) + 1;
4568	    });
4569	    const state = innerNodes.map(() => 0);
4570	    const existsLayout = (idx: number): number => layouts[idx] - 1;
4571	    const nullLayout = (idx: number): number => {
4572	      const node = innerNodes[idx];
4573	      const field = (node.parent as ReachNode).objectRule.fields.get(node.fieldName as string) as FieldRule;
4574	      // null 布局紧挨在存在之前（可缺失时最前为缺失）
4575	      return ruleAcceptsNullValue(field.rule) ? layouts[idx] - 2 : -1;
4576	    };
4577	
4578	    // 按当前布局把全部中间节点自顶向下物化到父对象，并登记“存在且祖先链存在”
4579	    // 的活动节点。每轮都显式删除/写入，避免上一轮的陈旧挂载在父对象重新存在时
4580	    // 复活。
4581	    const active = new Set<ReachNode>();
4582	    const materialize = (): void => {
4583	      active.clear();
4584	      for (let idx = 0; idx < innerNodes.length; idx += 1) {
4585	        const node = innerNodes[idx];
4586	        const parentObj = work.get(node.parent as ReachNode) as Record<string, unknown>;
4587	        const name = node.fieldName as string;
4588	        const layout = state[idx];
4589	        if (layout === existsLayout(idx)) {
4590	          parentObj[name] = work.get(node) as Record<string, unknown>;
4591	          if (node.parent === this.rootNode || active.has(node.parent)) {
4592	            active.add(node);
4593	          }
4594	        } else if (layout === nullLayout(idx)) {
4595	          parentObj[name] = null;
4596	        } else {
4597	          delete parentObj[name];
4598	        }
4599	      }
4600	    };
4601	
4602	    const chainActive = (node: ReachNode): boolean => {
4603	      let cur: ReachNode | null = node;
4604	      while (cur !== this.rootNode && cur !== null) {
4605	        if (!active.has(cur)) {
4606	          return false;
4607	        }
4608	        cur = cur.parent;
4609	      }
4610	      return true;
4611	    };
4612	
4613	    // 钉值涉及的节点（叶对象自身或其祖先）必须取“存在”布局
4614	    const pinnedNodePaths: Array<readonly string[]> = [];
4615	    for (const pin of pins.values()) {
4616	      pinnedNodePaths.push(pin.segments.slice(0, -1));
4617	    }
4618	    const nodeForcedExists = (node: ReachNode): boolean =>
4619	      pinnedNodePaths.some(
4620	        (p) => p.length >= node.path.length && node.path.every((seg, i) => seg === p[i]),
4621	      );
4622	
4623	    const problems: StructureProblem[] = [];
4624	    const check = (): Record<string, unknown> | typeof NO_WITNESS => {
4625	      materialize();
4626	      problems.length = 0;
4627	      checkRule(this.rootRule, rootObj, '', problems);
4628	      if (problems.length === 0 && predicate(rootObj)) {
4629	        return rootObj;
4630	      }
4631	      return NO_WITNESS;
4632	    };
4633	
4634	    // 标量维度状态：0 起；可选时首态为缺失，可空时紧接 null，之后依次 values。
4635	    const dimCount = (dim: ReachDim): number =>
4636	      (dim.optional ? 1 : 0) + (dim.nullable ? 1 : 0) + dim.values.length;
4637	    const missingState = (dim: ReachDim): number => (dim.optional ? 0 : -1);
4638	    const nullState = (dim: ReachDim): number => (dim.nullable ? (dim.optional ? 1 : 0) : -1);
4639	    const valueOffset = (dim: ReachDim): number => (dim.optional ? 1 : 0) + (dim.nullable ? 1 : 0);
4640	
4641	    const pinAt = (dim: ReachDim): BranchConditionValue | undefined =>
4642	      pins.get(reachPointer(dim.node, dim.name))?.value;
4643	
4644	    const enumDims = (dimIdx: number): Record<string, unknown> | typeof NO_WITNESS => {
4645	      if (dimIdx === this.dims.length) {
4646	        return check();
4647	      }
4648	      const dim = this.dims[dimIdx];
4649	      const obj = work.get(dim.node) as Record<string, unknown>;
4650	      const pinned = pinAt(dim);
4651	      // 祖先链不“存在”：该维取值无意义（叶字段不可达），只走一态；
4652	      // 钉值也不会写入，谓词（首支命中）自会排除需要该条件成立的情形。
4653	      if (!chainActive(dim.node)) {
4654	        return enumDims(dimIdx + 1);
4655	      }
4656	      if (pinned !== undefined) {
4657	        obj[dim.name] = pinned;
4658	        return enumDims(dimIdx + 1);
4659	      }
4660	      for (let s = 0; s < dimCount(dim); s += 1) {
4661	        if (s === missingState(dim)) {
4662	          delete obj[dim.name];
4663	        } else if (s === nullState(dim)) {
4664	          obj[dim.name] = null;
4665	        } else {
4666	          obj[dim.name] = dim.values[s - valueOffset(dim)];
4667	        }
4668	        const found = enumDims(dimIdx + 1);
4669	        if (found !== NO_WITNESS) {
4670	          return found;
4671	        }
4672	      }
4673	      return NO_WITNESS;
4674	    };
4675	
4676	    const enumInner = (idx: number): Record<string, unknown> | typeof NO_WITNESS => {
4677	      if (idx === innerNodes.length) {
4678	        // 全部中间节点布局已定：先物化并登记活动节点，标量维度再据此判定
4679	        // 其祖先链是否“存在”。
4680	        materialize();
4681	        return enumDims(0);
4682	      }
4683	      const node = innerNodes[idx];
4684	      const forcedExists = nodeForcedExists(node);
4685	      for (let layout = 0; layout < layouts[idx]; layout += 1) {
4686	        // 钉值在该节点（或其后代）上时，缺失/null 布局不可能满足谓词，直接跳过
4687	        if (forcedExists && layout !== existsLayout(idx)) {
4688	          continue;
4689	        }
4690	        state[idx] = layout;
4691	        const found = enumInner(idx + 1);
4692	        if (found !== NO_WITNESS) {
4693	          return found;
4694	        }
4695	      }
4696	      return NO_WITNESS;
4697	    };
4698	
4699	    return enumInner(0);
4700	  }
