4702	  // 找一份合格正文：根可空且无钉值时先尝试 JSON null（任何字段指针在 null 上
4703	  // 都取不到值、不命中分支），再在对象域上求解；有钉值时只能是对象正文。
4704	  findWitness(pins: PinMap, predicate: (value: unknown) => boolean): Witness {
4705	    if (pins.size === 0 && ruleAcceptsNullValue(this.rootRule)) {
4706	      if (predicate(null)) {
4707	        return null;
4708	      }
4709	    }
4710	    return this.findObject(pins, predicate);
4711	  }
4712	
4713	  // 两支钉值是否相容：同一规范指针上常量严格相等（0 与 -0 视为相等）才存在
4714	  // 同时满足两支的正文；不同指针恒相容（含共享祖先下的兄弟字段、不同祖先）。
4715	  private mergePins(a: PinMap, b: PinMap): Map<string, ReachPin> | null {
4716	    const merged = new Map(a);
4717	    for (const [key, pin] of b) {
4718	      const existing = merged.get(key);
4719	      if (existing !== undefined && existing.value !== pin.value) {
4720	        return null;
4721	      }
4722	      merged.set(key, pin);
4723	    }
4724	    return merged;
4725	  }
