4727	  private example(value: unknown, routePath: string): ReachExample {
4728	    return {
4729	      method: 'POST',
4730	      path: routePath,
4731	      headers: { 'Content-Type': 'application/json' },
4732	      body: JSON.stringify(value),
4733	    };
4734	  }
