4736	  solve(routePath: string): { branches: BranchReach[]; fallback: FallbackReach } {
4737	    const analyses = this.branches.map((branch) => analyzeBranchConditions(branch, this.rootNode));
4738	
4739	    const branchResults: BranchReach[] = [];
4740	    for (let i = 0; i < this.branches.length; i += 1) {
4741	      const branch = this.branches[i];
4742	      const analysis = analyses[i];
4743	      if (!analysis.ok || analysis.pins === undefined) {
4744	        branchResults.push({ id: branch.id, status: 'contradictory', reasons: analysis.reasons });
4745	        continue;
4746	      }
4747	
4748	      // 存在合格正文首先命中此支？
4749	      const direct = this.findWitness(analysis.pins, (value) => this.firstMatch(value) === i);
4750	      if (direct !== NO_WITNESS) {
4751	        branchResults.push({ id: branch.id, status: 'reachable', example: this.example(direct, routePath) });
4752	        continue;
4753	      }
4754	
4755	      // 满足此支的合格正文必然首先命中某些前序分支——逐支给出共同遮挡者
4756	      const coveredBy: string[] = [];
4757	      for (let j = 0; j < i; j += 1) {
4758	        const prior = analyses[j];
4759	        if (!prior.ok || prior.pins === undefined) {
4760	          continue;
4761	        }
4762	        const merged = this.mergePins(analysis.pins, prior.pins);
4763	        if (merged === null) {
4764	          continue;
4765	        }
4766	        // 同时满足 i 与 j、且 j 之前所有分支都不命中（首支恰为 j）的合格正文
4767	        const witness = this.findWitness(merged, (value) => this.firstMatch(value) === j);
4768	        if (witness !== NO_WITNESS) {
4769	          coveredBy.push(this.branches[j].id);
4770	        }
4771	      }
4772	      branchResults.push({
4773	        id: branch.id,
4774	        status: 'covered',
4775	        coveredBy,
4776	        message:
4777	          `存在满足本支全部条件的合格正文，但它们首先命中的都是前序分支；` +
4778	          `前序分支 ${JSON.stringify(coveredBy)} 的命中区域并集已覆盖本支，本支永远不会被首先选中`,
4779	      });
4780	    }
4781	
4782	    // 兜底：存在任何分支都不命中的合格正文（含根为 JSON null）即可达
4783	    const fallbackBody = this.findWitness(new Map(), (value) => this.firstMatch(value) === null);
4784	    let fallback: FallbackReach;
4785	    if (fallbackBody !== NO_WITNESS) {
4786	      fallback = { status: 'reachable', example: this.example(fallbackBody, routePath) };
4787	    } else {
4788	      const noWitness = NO_WITNESS;
4789	      const coveredBy = this.branches
4790	        .map((branch, j) => {
4791	          const analysis = analyses[j];
4792	          if (!analysis.ok || analysis.pins === undefined) {
4793	            return noWitness;
4794	          }
4795	          const witness = this.findWitness(analysis.pins, (value) => this.firstMatch(value) === j);
4796	          return witness !== noWitness ? branch.id : noWitness;
4797	        })
4798	        .filter((id): id is string => id !== noWitness);
4799	      fallback = {
4800	        status: 'covered',
4801	        coveredBy,
4802	        message:
4803	          `没有任何合格正文落到兜底：全部合格正文都被分支 ${JSON.stringify(coveredBy)} 的命中区域并集覆盖`,
4804	      };
4805	    }
4806	
4807	    return { branches: branchResults, fallback };
4808	  }
4809	}
