4811	// 选择诊断目标接口并执行范围预检；任何不满足都抛 ReachError（退出 2）
4812	function selectReachEndpoint(
4813	  specs: readonly EndpointSpec[],
4814	  configFile: string,
4815	  routePath: string,
4816	): { endpoint: EndpointSpec; index: number } {
4817	  const postMatches = specs
4818	    .map((endpoint, index) => ({ endpoint, index }))
4819	    .filter((entry) => entry.endpoint.method === 'POST' && entry.endpoint.path === routePath);
4820	
4821	  if (postMatches.length === 0) {
4822	    const existing = specs.filter((ep) => ep.method === 'POST').map((ep) => `POST ${ep.path}`);
4823	    throw new ReachError(
4824	      `场景文件 ${configFile} 中不存在 POST 接口 ${JSON.stringify(routePath)}。` +
4825	        (existing.length > 0 ? `现有的 POST 接口：${existing.join('，')}` : '该配置没有 POST 接口'),
4826	    );
4827	  }
4828	
4829	  const { endpoint, index } = postMatches[0];
4830	  const where = `endpoints[${index}]`;
4831	  if (endpoint.branches.length === 0) {
4832	    throw new ReachError(
4833	      `${where}（POST ${routePath}）未声明 branches：reach 仅诊断声明了响应分支的接口`,
4834	    );
4835	  }
4836	  if (!endpoint.bodyRule || endpoint.bodyRule.kind !== 'object') {
4837	    throw new ReachError(
4838	      `${where}.requestBody ${endpoint.bodyRule ? `的类型为 "${endpoint.bodyRule.kind}"` : ''}：` +
4839	        'reach 仅支持根 requestBody 为 object（可附 nullable）的分支接口',
4840	    );
4841	  }
4842	
4843	  // when 指针范围预检：可为多段，但每段都必须是“所在对象已声明的自有字段”，
4844	  // 中间节点必须为 object，终点必须是现有标量规则。根指针、穿过数组或标量、
4845	  // 未声明字段、对象/数组终点都整份拒绝（其他未引用字段仍按递归规则处理）。
4846	  for (let b = 0; b < endpoint.branches.length; b += 1) {
4847	    const branch = endpoint.branches[b];
4848	    for (const condition of branch.conditions) {
4849	      const condWhere = `${where}.branches[${b}].when[${JSON.stringify(condition.pointer)}]`;
4850	      if (condition.segments.length === 0) {
4851	        throw new ReachError(
4852	          `${condWhere} 是根指针 ""：reach 的条件指针必须指向对象字段（至少一段），根指针超出诊断范围`,
4853	        );
4854	      }
4855	      let objectRule: Extract<BodyRule, { kind: 'object' }> = endpoint.bodyRule;
4856	      for (let k = 0; k < condition.segments.length; k += 1) {
4857	        const name = condition.segments[k];
4858	        const isLast = k === condition.segments.length - 1;
4859	        const field = objectRule.fields.get(name);
4860	        if (!field) {
4861	          throw new ReachError(
4862	            `${condWhere} 的第 ${k} 段 ${JSON.stringify(name)} 不是所在对象的已声明字段：` +
4863	              'reach 仅诊断沿已声明自有字段的条件（未声明字段仍按 additionalProperties 等现有规则处理）',
4864	          );
4865	        }
4866	        if (!isLast) {
4867	          if (field.rule.kind !== 'object') {
4868	            throw new ReachError(
4869	              `${condWhere} 的第 ${k} 段 ${JSON.stringify(name)} 规则类型为 "${field.rule.kind}"：` +
4870	                'reach 的多段指针只能穿过 object 字段（穿过数组或标量超出诊断范围）',
4871	            );
4872	          }
4873	          objectRule = field.rule;
4874	        } else if (field.rule.kind === 'object' || field.rule.kind === 'array') {
4875	          throw new ReachError(
4876	            `${condWhere} 的终点字段 ${JSON.stringify(name)} 规则类型为 "${field.rule.kind}"：` +
4877	              'reach 仅支持终点为标量字段的条件，对象/数组终点超出诊断范围',
4878	          );
4879	        }
4880	      }
4881	    }
4882	  }
4883	
4884	  return { endpoint, index };
4885	}
