4965	function writeResponse(
4966	  res: http.ServerResponse,
4967	  status: number,
4968	  headers: { readonly [name: string]: string },
4969	  body: string,
4970	): void {
4971	  try {
4972	    res.writeHead(status, headers);
4973	    res.end(body === '' ? undefined : body);
4974	  } catch {
4975	    // 预留之后客户端可能已断开：响应仍计为已消费，发送失败仅静默忽略
4976	  }
4977	}
