4979	function versionHeaders(
4980	  version: number,
4981	  extra?: { readonly [name: string]: string },
4982	): { [name: string]: string } {
4983	  // 无原型对象：配置中名为 "__proto__" 的响应头在合并时不丢失
4984	  const headers: { [name: string]: string } = Object.create(null);
