5052	function buildScenePlanned(item: ResponseSpec, version: number): PlannedResponseSnapshot {
5053	  return {
5054	    kind: 'scene',
5055	    status: item.status,
5056	    headers: buildSceneHeaders(item, version),
5057	    body: item.body,
5058	  };
5059	}
