5075	// 按计划快照写出；writeHead/end 在已断开套接字上抛错时标记为中断（消费已成立）。
5076	function writePlanned(
5077	  res: http.ServerResponse,
5078	  planned: PlannedResponseSnapshot,
5079	  recordId: number,
5080	): void {
5081	  try {
5082	    res.writeHead(planned.status, { ...planned.headers });
5083	    res.end(planned.body === '' ? undefined : planned.body);
5084	  } catch {
5085	    requestLog.markDelivered(recordId, 'interrupted');
5086	  }
5087	}
