5089	// 挂载一次写出生命周期跟踪。每个被记录的请求恰好回复一次，故在接收完成后立即挂载：
5090	// 延迟期间断开也能标为中断；'sent' 为终态，随后连接正常关闭不回退。
5091	function attachDeliveryTracking(res: http.ServerResponse, recordId: number): void {
5092	  let settled = false;
5093	  const settle = (status: DeliveryStatus): void => {
5094	    if (settled) {
5095	      return;
5096	    }
5097	    settled = true;
5098	    requestLog.markDelivered(recordId, status);
5099	  };
5100	  res.once('finish', () => settle('sent'));
5101	  res.once('close', () => settle(res.writableFinished ? 'sent' : 'interrupted'));
5102	  res.once('error', () => settle('interrupted'));
5103	}
5104	
5105	// 延迟结束才按接收时的计划快照发送；即便客户端提前断开也继续计时（消费在预留时已成立）
5106	function schedulePlannedResponse(
5107	  res: http.ServerResponse,
5108	  planned: PlannedResponseSnapshot,
5109	  delay: number,
5110	  recordId: number,
5111	): void {
5112	  const timer = setTimeout(() => {
5113	    pendingTimers.delete(timer);
5114	    writePlanned(res, planned, recordId);
5115	  }, delay);
5116	  pendingTimers.add(timer);
5117	}
