5338	function shutdown(): void {
5339	  if (shuttingDown) {
5340	    return;
5341	  }
5342	  shuttingDown = true;
5343	  // 取消所有尚未发出的延迟响应
5344	  for (const timer of pendingTimers) {
5345	    clearTimeout(timer);
5346	  }
5347	  pendingTimers.clear();
5348	  // 关闭监听并断开空闲/在途连接，随后正常退出（退出码 0）
5349	  try {
5350	    server.closeAllConnections();
5351	  } catch {
5352	    // 旧版本兜底：忽略，下面的 close/超时仍会结束进程
5353	  }
5354	  server.close(() => process.exit(0));
5355	  setTimeout(() => process.exit(0), 2000).unref();
5356	}
