5490	function parseServeArgv(argv: readonly string[]): ServeOptions {
5491	  let config: string | undefined;
5492	  let port: number | undefined;
5493	
5494	  const readValue = (flag: string, inline: string | undefined, index: number): [string, number] => {
5495	    if (inline !== undefined) {
5496	      return [inline, index];
5497	    }
5498	    const value = argv[index + 1];
5499	    if (value === undefined) {
5500	      cliFail(`serve: 参数 ${flag} 缺少取值`);
5501	    }
5502	    return [value as string, index + 1];
5503	  };
5504	
5505	  for (let i = 0; i < argv.length; i += 1) {
5506	    const token = argv[i];
5507	    if (token === '--help' || token === '-h') {
5508	      process.stdout.write(`${helpText()}\n`);
5509	      process.exit(0);
5510	    }
5511	
5512	    let flag = token;
5513	    let inline: string | undefined;
5514	    const eq = token.indexOf('=');
5515	    if (eq >= 0) {
5516	      flag = token.slice(0, eq);
5517	      inline = token.slice(eq + 1);
5518	    }
5519	
5520	    if (flag === '--config' || flag === '-c') {
5521	      [config, i] = readValue(flag, inline, i);
5522	    } else if (flag === '--port' || flag === '-p') {
5523	      let value: string;
5524	      [value, i] = readValue(flag, inline, i);
5525	      if (!/^\d+$/.test(value)) {
5526	        cliFail(`serve: 端口必须是整数，收到 "${value}"`);
5527	      }
5528	      port = Number(value);
5529	      if (port < 0 || port > 65535) {
5530	        cliFail(`serve: 端口必须在 0 至 65535 之间，收到 ${port}`);
5531	      }
5532	    } else {
5533	      cliFail(`serve: 不支持的命令行参数: ${token}`);
5534	    }
5535	  }
5536	
5537	  if (config === undefined) {
5538	    cliFail('serve: 缺少必填参数 --config <file>');
5539	  }
5540	  if (port === undefined) {
5541	    cliFail('serve: 缺少必填参数 --port <port>');
5542	  }
5543	  return { config, port };
5544	}
