1	// 进程内请求记录的回归测试（真实本机服务 + 真实 HTTP/原始套接字请求）
2	//
3	// 覆盖：
4	// - 记录内容：方法、含查询串目标、原始请求头（含重复头）、正文原始字节
5	//   （合法 UTF-8 文本 / 非法 UTF-8 base64 无损）、接收时配置版本、匹配/校验结论、
6	//   400 实际差异报告、消费位置（末项复用记同一位置；400/404 无位置）、
7	//   计划响应（场景/框架：状态、应用层头含准确版本头、正文）；
8	// - 写出生命周期：延迟期间 pending → sent；写出前断开 interrupted（仍消费）；
9	// - 清空：移除当时全部记录（含 pending），不取消响应、不改变配置/版本/序列，
10	//   清空前完整接收的请求之后完成也不再出现；编号清空与重载后均不复用；
11	// - reload：成功/失败都保留记录；在途请求钉住旧版本与旧计划响应；后续请求用新版本；
12	// - 管理范围（/__contractlab 本身及 /__contractlab/ 前缀）不记录；查询不推进序列；
13	// - 未收完整即断开、超出正文上限（413）：不创建记录、不消费序列。
14	
15	import assert from 'node:assert/strict';
16	import http from 'node:http';
17	import net from 'node:net';
18	import test from 'node:test';
19	import { makeTempDir, startServer, writeConfig, type RunningServer } from './helpers.ts';
20	
21	const SLOW_DELAY = 400;
22	
23	function config(): unknown {
24	  return {
25	    endpoints: [
26	      {
27	        method: 'GET',
28	        path: '/api/seq',
29	        responses: [
30	          { status: 200, headers: { 'X-Item': 'one' }, body: 'one', delay: 0 },
31	          { status: 201, headers: { 'X-Item': 'two' }, body: 'two', delay: 0 },
32	          { status: 202, headers: { 'X-Item': 'last' }, body: 'last', delay: 0 },
33	        ],
34	      },
35	      {
36	        method: 'GET',
37	        path: '/api/slow',
38	        responses: [
39	          { status: 200, headers: {}, body: 'slow-one', delay: SLOW_DELAY },
40	          { status: 201, headers: {}, body: 'slow-two', delay: SLOW_DELAY },
41	        ],
42	      },
43	      {
44	        method: 'POST',
45	        path: '/api/echo',
46	        requestBody: {
47	          type: 'object',
48	          fields: { id: { type: 'integer', required: true } },
49	          additionalProperties: false,
50	        },
51	        responses: [{ status: 200, headers: {}, body: 'echo-ok', delay: 0 }],
52	      },
53	    ],
54	  };
55	}
