// 返回可直接作为 RequestRecord 使用的对象（不按当前配置重判任何结论）。
function validateStoredRecord(raw: unknown, index: number, file: string): RequestRecord {
  const where = `records[${index}]`;
  if (!isPlainObject(raw)) {
    storeFail(file, where, '必须是对象');
  }
