    if (
      key !== 'id' &&
      key !== 'receivedAt' &&
      key !== 'request' &&
      key !== 'configVersion' &&
      key !== 'matched' &&
      key !== 'endpoint' &&
      key !== 'bodyValidationPassed' &&
      key !== 'bodyRejection' &&
      key !== 'branchSelection' &&
      key !== 'sequencePosition' &&
      key !== 'sequenceLength' &&
      key !== 'plannedResponse' &&
      key !== 'delivery'
