export async function startServer(configPath: string, timeoutMs = 20_000): Promise<RunningServer> {
  const child = spawn(process.execPath, [APP_PATH, 'serve', '--config', configPath, '--port', '0'], {
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let stdout = '';
  let stderr = '';
  child.stdout.setEncoding('utf8').on('data', (d: string) => (stdout += d));
  child.stderr.setEncoding('utf8').on('data', (d: string) => (stderr += d));

  const port = await new Promise<number>((resolve, reject) => {
    let settled = false;
    const fail = (e: Error): void => {
      if (!settled) {
        settled = true;
        clearTimeout(timer);
        child.kill('SIGKILL');
        reject(e);
      }
    };
    const timer = setTimeout(() => {
      fail(
        new Error(
          `服务 ${timeoutMs}ms 内未输出监听地址（疑似卡住）\nstdout:\n${stdout}\nstderr:\n${stderr}`,
        ),
      );
    }, timeoutMs);
    child.stdout.on('data', () => {
      const m = stdout.match(/listening on http:\/\/127\.0\.0\.1:(\d+)/);
      if (m && !settled) {
        settled = true;
        clearTimeout(timer);
        resolve(Number(m[1]));
      }
    });
    child.on('exit', (code) => {
      fail(new Error(`服务在监听前退出（code=${code}）\nstdout:\n${stdout}\nstderr:\n${stderr}`));
    });
  });

  const close = async (): Promise<void> => {
    if (child.exitCode !== null || child.signalCode !== null) {
      return;
    }
    child.kill('SIGTERM');
    const force = setTimeout(() => child.kill('SIGKILL'), 5_000);
    await once(child, 'exit').catch(() => undefined);
    clearTimeout(force);
  };

  return { port, stderr: () => stderr, close };
}

